parameters.jsCode:
// Sample data in the shape QuickBooks returns, with due dates relative to today,
// so every route runs: a first nudge, a second stage, a final notice, an escalation,
// a customer on the do-not-chase list, one with no billing email and one in cooldown.
const day = (n) => $now.minus({ days: n }).toFormat('yyyy-MM-dd');
const inv = (id, doc, cust, name, email, dueAgo, balance, currency = 'USD') => ({
  Id: id, DocNumber: doc, TxnDate: day(dueAgo + 30), DueDate: day(dueAgo),
  TotalAmt: balance, Balance: balance,
  CustomerRef: { value: cust, name },
  BillEmail: email ? { Address: email } : undefined,
  CurrencyRef: { value: currency },
});
return [{ json: {
  invoices: [
    inv('201', '1041', '11', 'Harbor Dental Group', 'user@example.com', 3, 1250),
    inv('202', '1033', '12', 'Pine Street Bakery', 'user@example.com', 9, 480.5),
    inv('203', '1029', '13', 'Atlas Freight LLC', 'user@example.com', 33, 3900),
    inv('204', '1037', '13', 'Atlas Freight LLC', 'user@example.com', 16, 725),
    inv('205', '1012', '14', 'Northside Fitness', 'user@example.com', 52, 2100),
    inv('206', '1044', '15', 'Greenleaf Studio', '', 12, 610),
    inv('207', '1039', '16', 'Bluebird Events', 'user@example.com', 20, 1800),
    inv('208', '1045', '17', 'Maple Clinic', 'user@example.com', 8, 300),
  ],
  // What the Reminder log sheet would already hold.
  log: [
    { logged_at: $now.minus({ days: 10 }).toISO(), customer_id: '13', invoice_id: '203', invoice_number: '1029', stage: 3, action: 'sent' },
    { logged_at: $now.minus({ days: 8 }).toISO(), customer_id: '12', invoice_id: '202', invoice_number: '1033', stage: 1, action: 'sent' },
    { logged_at: $now.minus({ days: 24 }).toISO(), customer_id: '14', invoice_id: '205', invoice_number: '1012', stage: 3, action: 'sent' },
    { logged_at: $now.minus({ days: 14 }).toISO(), customer_id: '14', invoice_id: '205', invoice_number: '1012', stage: 4, action: 'drafted' },
    { logged_at: $now.minus({ days: 2 }).toISO(), customer_id: '17', invoice_id: '208', invoice_number: '1045', stage: 1, action: 'sent' },
  ],
  // What the Do not chase sheet would hold.
  doNotChase: [
    { customer_id: '16', invoice_number: '', customer_email: '', reason: 'Agreed payment plan', until: $now.plus({ days: 30 }).toFormat('yyyy-MM-dd') },
  ],
} }];

// Decides who gets a reminder today. This is plain code, so every decision can be audited:
// Claude never chooses who is chased, which stage applies or what amounts are quoted.
const s = $('Settings').first().json;
const isTest = $('Test with sample invoices').isExecuted;

let invoices, log, blocks;
if (isTest) {
  const sample = $('Sample overdue invoices').first().json;
  invoices = sample.invoices; log = sample.log; blocks = sample.doNotChase;
} else {
  invoices = $('Get overdue invoices').all().map((i) => i.json).filter((i) => i && i.Id);
  log = $('Read reminder log').all().map((i) => i.json).filter((r) => r && r.invoice_id);
  blocks = $('Read do-not-chase list').all().map((i) => i.json)
    .filter((r) => r && (r.customer_id || r.invoice_number || r.customer_email));
}

const num = (v, d) => (v === '' || v === null || v === undefined || isNaN(Number(v)) ? d : Number(v));
const STAGES = [
  { n: 1, key: 'nudge', label: 'friendly nudge', days: num(s.stage1Days, 1) },
  { n: 2, key: 'reminder', label: 'reminder', days: num(s.stage2Days, 7) },
  { n: 3, key: 'firm', label: 'firm reminder', days: num(s.stage3Days, 14) },
  { n: 4, key: 'final', label: 'final notice', days: num(s.finalNoticeDays, 30) },
];
for (let i = 1; i < STAGES.length; i++) {
  if (STAGES[i].days <= STAGES[i - 1].days) throw new Error('Settings: stage days must increase (stage1Days < stage2Days < stage3Days < finalNoticeDays).');
}
const escalateDays = num(s.escalateDays, 45);
const cooldownDays = num(s.cooldownDays, 5);
const minBalance = num(s.minBalance, 1);
const maxEmails = num(s.maxEmailsPerRun, 20);
const sendMode = String(s.sendMode || 'draft').toLowerCase() === 'send' ? 'send' : 'draft';
const today = $today;

const key = (v) => String(v ?? '').trim().toLowerCase();
const parseDay = (v) => {
  if (!v) return null;
  const d = DateTime.fromISO(String(v).slice(0, 10));
  return d.isValid ? d.startOf('day') : null;
};
const emailOk = (e) => /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+(\s*,\s*[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+)*$/.test(String(e || '').trim());

// What has already happened, from the log. Only sent or drafted rows count as a stage done.
const lastStage = {}, escalated = new Set(), lastContact = {};
for (const r of log) {
  const id = String(r.invoice_id);
  const action = key(r.action);
  if (action === 'sent' || action === 'drafted') {
    lastStage[id] = Math.max(lastStage[id] || 0, num(r.stage, 0));
    const at = DateTime.fromISO(String(r.logged_at || ''));
    const c = String(r.customer_id || '');
    if (at.isValid && c && (!lastContact[c] || at > lastContact[c])) lastContact[c] = at;
  }
  if (action === 'escalated') escalated.add(id);
}

// Do-not-chase rows: disputes, payment plans, VIPs. An empty 'until' means indefinitely.
const activeBlocks = blocks.filter((b) => { const u = parseDay(b.until); return !u || u >= today; });
const blockFor = (inv) => activeBlocks.find((b) =>
  (b.customer_id && key(b.customer_id) === key(inv.CustomerRef?.value)) ||
  (b.invoice_number && key(b.invoice_number) === key(inv.DocNumber)) ||
  (b.customer_email && inv.BillEmail?.Address && key(inv.BillEmail.Address).includes(key(b.customer_email))));

const skipped = { blocked: [], noEmail: [], cooldown: [], belowMinimum: 0, runLimit: [] };
const customers = {};
for (const inv of invoices) {
  const balance = num(inv.Balance, 0);
  const due = parseDay(inv.DueDate);
  if (!due) continue;
  const daysOverdue = Math.floor(today.diff(due, 'days').days);
  if (daysOverdue < 1) continue;
  if (balance < minBalance) { skipped.belowMinimum++; continue; }
  const name = inv.CustomerRef?.name || 'Customer ' + (inv.CustomerRef?.value || '?');
  const block = blockFor(inv);
  if (block) { skipped.blocked.push(`${name} #${inv.DocNumber} (${block.reason || 'no reason given'})`); continue; }
  let stageDue = 0;
  for (const st of STAGES) if (daysOverdue >= st.days) stageDue = st.n;
  const done = lastStage[String(inv.Id)] || 0;
  const cid = String(inv.CustomerRef?.value || name);
  const c = customers[cid] || (customers[cid] = { customerId: cid, customerName: name, emails: [], invoices: [] });
  if (inv.BillEmail?.Address) c.emails.push(String(inv.BillEmail.Address).trim());
  c.invoices.push({
    id: String(inv.Id), number: String(inv.DocNumber || inv.Id), issued: inv.TxnDate || '', due: due.toFormat('yyyy-MM-dd'),
    daysOverdue, balance, currency: inv.CurrencyRef?.value || s.defaultCurrency || 'USD',
    // One step at a time: a customer always hears the earlier stages before a final notice.
    stageDue, stageDone: done, needsStage: stageDue > done ? Math.min(stageDue, done + 1) : 0,
    escalate: daysOverdue >= escalateDays && !escalated.has(String(inv.Id)),
  });
}

const esc_ = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n, cur) => `${cur} ${Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const totals = (list) => {
  const t = {};
  for (const i of list) t[i.currency] = (t[i.currency] || 0) + i.balance;
  return Object.entries(t).map(([cur, v]) => money(v, cur)).join(' + ');
};

const out = [];
let emails = 0;
const ordered = Object.values(customers).sort((a, b) =>
  Math.max(...b.invoices.map((i) => i.daysOverdue)) - Math.max(...a.invoices.map((i) => i.daysOverdue)));
const logBase = (c, i) => ({
  customer_id: c.customerId, customer_name: c.customerName, invoice_id: i.id, invoice_number: i.number,
  due_date: i.due, days_overdue: i.daysOverdue, balance: i.balance, currency: i.currency,
});

for (const c of ordered) {
  c.invoices.sort((a, b) => b.daysOverdue - a.daysOverdue);
  const needing = c.invoices.filter((i) => i.needsStage > 0);
  const to = [...new Set(c.emails)].join(', ');

  if (needing.length) {
    const stage = Math.max(...needing.map((i) => i.needsStage));
    const last = lastContact[c.customerId];
    if (!emailOk(to)) {
      skipped.noEmail.push(c.customerName);
    } else if (last && today.diff(last.startOf('day'), 'days').days < cooldownDays) {
      skipped.cooldown.push(`${c.customerName} (last contact ${last.toFormat('d LLL')})`);
    } else if (emails >= maxEmails) {
      skipped.runLimit.push(c.customerName);
    } else {
      emails++;
      const st = STAGES[stage - 1];
      const action = isTest ? 'preview' : (st.key === 'final' || sendMode === 'draft' ? 'draft' : 'send');
      out.push({ json: {
        kind: 'reminder', isTest, action, stage, stageKey: st.key,
        customerId: c.customerId, customerName: c.customerName, to,
        invoices: c.invoices, invoiceCount: c.invoices.length,
        maxDaysOverdue: c.invoices[0].daysOverdue, totalText: totals(c.invoices),
        previousReminders: Math.max(...c.invoices.map((i) => i.stageDone)),
        logRows: needing.map((i) => ({ ...logBase(c, i), email: to, stage: i.needsStage })),
      } });
    }
  }

  const esc = c.invoices.filter((i) => i.escalate);
  if (esc.length) {
    const lines = esc.map((i) => `• #${i.number}: ${money(i.balance, i.currency)}, ${i.daysOverdue} days overdue (last reminder: ${i.stageDone ? STAGES[i.stageDone - 1].label : 'none yet'})`);
    out.push({ json: {
      kind: isTest ? 'preview' : 'escalation', isTest, customerId: c.customerId, customerName: c.customerName,
      slackText: `:rotating_light: *${esc_(c.customerName)}* has invoices more than ${escalateDays} days overdue. Email reminders end with the final notice, so this needs a person: call them, agree a plan (and add them to Do not chase), or decide next steps.\n${lines.join('\n')}`,
      logRows: esc.map((i) => ({ ...logBase(c, i), email: to, stage: 'escalation' })),
    } });
  }
}

// One summary for the day. Skipped when nothing is overdue, unless you ask for it.
const all = Object.values(customers).flatMap((c) => c.invoices);
const reminders = out.filter((o) => o.json.kind === 'reminder');
const escalations = out.filter((o) => o.json.slackText && o.json.logRows && o.json.logRows[0]?.stage === 'escalation');
if (all.length || skipped.blocked.length || skipped.belowMinimum || s.postEmptySummary) {
  const actions = isTest ? `${reminders.length} test previews (nothing sent)` :
    `${reminders.filter((r) => r.json.action === 'send').length} sent, ${reminders.filter((r) => r.json.action === 'draft').length} saved as Gmail drafts for review`;
  const parts = [
    `:bar_chart: *Overdue invoices${isTest ? ' [TEST]' : ''}:* ${all.length} being chased, ${all.length ? totals(all) : 'nothing'} outstanding.`,
    `Reminders today: ${actions}. Escalations: ${escalations.length}.`,
  ];
  if (skipped.noEmail.length) parts.push(`No billing email in QuickBooks: ${esc_(skipped.noEmail.join(', '))}`);
  if (skipped.blocked.length) parts.push(`On Do not chase: ${esc_(skipped.blocked.join(', '))}`);
  if (skipped.cooldown.length) parts.push(`Waiting (contacted in the last ${cooldownDays} days): ${esc_(skipped.cooldown.join(', '))}`);
  if (skipped.runLimit.length) parts.push(`Held for tomorrow (run limit ${maxEmails}): ${esc_(skipped.runLimit.join(', '))}`);
  if (skipped.belowMinimum) parts.push(`${skipped.belowMinimum} invoice(s) below the ${minBalance} minimum were ignored.`);
  out.push({ json: { kind: isTest ? 'preview' : 'summary', isTest, slackText: parts.join('\n'), skipped } });
}
return out;

