parameters.jsCode:
// Claude wrote two short paragraphs. Code adds the subject, the invoice table and the payment
// details, so every amount, number and date in the email comes straight from QuickBooks.
// If Claude's text breaks a rule (or the call failed), a fixed fallback for that stage is used.
const r = $('Split by kind').item.json;
const s = $('Settings').first().json;
const ai = ($json.output && typeof $json.output === 'object') ? $json.output : {};

const many = r.invoiceCount > 1;
const inv = many ? 'invoices' : 'invoice';
const first = !r.previousReminders;
const FALLBACK = {
  nudge: [`We hope all is well. This is a quick note that the ${inv} below ${many ? 'have' : 'has'} passed ${many ? 'their' : 'its'} due date, which may simply have been missed.`,
          `If you have already paid, thank you, and please ignore this note. If anything on the ${inv} looks wrong, just reply and we will sort it out.`],
  reminder: [`${first ? 'We are writing because' : 'We are following up on our earlier note, as'} the ${inv} below ${many ? 'are' : 'is'} still showing as unpaid on our side.`,
             `If payment is already on its way, please reply with the expected date. If there is a problem with the ${inv}, let us know and we will help.`],
  firm: [`The ${inv} below ${many ? 'are' : 'is'} now well past ${many ? 'their' : 'its'} due date and we have not yet received payment.`,
         'Please arrange payment this week, or reply with the date you expect to pay so we can update our records.'],
  final: [`This is our final reminder about the overdue balance below. ${first ? `The oldest invoice is now ${r.maxDaysOverdue} days past due` : 'We have written before'} and have not yet received payment${first ? '' : ' or a reply'}.`,
          'Please arrange payment or contact us within 7 days. After that, we will follow up by phone to agree next steps.'],
};
// Words that must never appear in an automated reminder. Word boundaries keep 'courtesy' allowed.
const BANNED = [/\bdiscount/, /\bwaive/, /\binterest\b/, /\blate fees?\b/, /\bpenalt/, /\blegal\b/, /\blawyers?\b/,
  /\battorneys?\b/, /\bsolicitors?\b/, /\bcourts?\b/, /\blawsuit/, /\bsue\b/, /\bcollections? agenc/, /\bdebt collect/,
  /\bcredit (report|score|rating)/, /\bbailiff/];
const clean = (t) => String(t ?? '').replace(/\r/g, '').replace(/[*_#`>]/g, '').replace(/\n{3,}/g, '\n\n').trim();

const problems = [];
let opening = clean(ai.opening), closing = clean(ai.closing);
for (const [label, text, max] of [['opening', opening, 600], ['closing', closing, 400]]) {
  const low = text.toLowerCase();
  if (!text) problems.push(`${label} missing`);
  if (text.length > max) problems.push(`${label} too long`);
  const hit = BANNED.find((w) => w.test(low));
  if (hit) problems.push(`${label} mentions "${low.match(hit)[0]}"`);
  if (/[$€£¥]|\d[\d,]*\.\d{2}|\b(usd|eur|gbp|cad|aud)\b/i.test(text)) problems.push(`${label} quotes an amount`);
  if (/https?:|www\.|@/.test(low)) problems.push(`${label} contains a link or address`);
  if (/^(hi|hello|dear|good (morning|afternoon))\b/i.test(text) || /(regards|sincerely|thanks,|thank you,)\s*$/i.test(text)) problems.push(`${label} adds a greeting or sign-off`);
}
const guard = problems.length ? 'fallback: ' + problems.join('; ') : 'ok';
if (problems.length) [opening, closing] = FALLBACK[r.stageKey];

const money = (n, cur) => `${cur} ${Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const fmt = (d) => DateTime.fromISO(d).toFormat('d LLL yyyy');
const rows = r.invoices.map((i) =>
  `  Invoice ${i.number}   due ${fmt(i.due)}   ${i.daysOverdue} day${i.daysOverdue === 1 ? '' : 's'} overdue   ${money(i.balance, i.currency)}`);
const nums = r.invoices.map((i) => i.number);
const list = nums.length === 1 ? `invoice ${nums[0]}` : `invoices ${nums.slice(0, 3).join(', ')}${nums.length > 3 ? ' and more' : ''}`;
const SUBJECT = {
  nudge: `Friendly reminder: ${list} from ${s.companyName}`,
  reminder: `Reminder: ${list} ${nums.length > 1 ? 'are' : 'is'} overdue`,
  firm: `Overdue: ${list} from ${s.companyName}`,
  final: `Final reminder: ${list} from ${s.companyName}`,
};

const body = [
  `Hi ${r.customerName},`,
  opening,
  rows.join('\n'),
  `Total outstanding: ${r.totalText}`,
  String(s.paymentInstructions || '').trim(),
  closing,
  String(s.signature || s.companyName).trim(),
].filter(Boolean).join('\n\n');

return { json: {
  isTest: r.isTest, action: r.action, stage: r.stage, stageKey: r.stageKey,
  to: r.to, customerName: r.customerName, subject: SUBJECT[r.stageKey], body, guard, logRows: r.logRows,
} };

// One log row per invoice that moved to a new stage. A failed send is logged as 'failed',
// which does not count as a stage done, so tomorrow's run tries again.
const s = $('Settings').first().json;
const out = [];
$input.all().forEach((item, i) => {
  const b = $('Build the email').itemMatching(i).json;
  const failed = Boolean(item.json.error);
  const action = failed ? 'failed' : (b.action === 'send' ? 'sent' : 'drafted');
  for (const row of b.logRows) {
    out.push({ json: {
      logged_at: $now.toISO(), mode: String(s.sendMode || 'draft'), ...row, action,
      gmail_id: item.json.id || item.json.message?.id || '',
      note: failed ? String(item.json.error?.message || item.json.error).slice(0, 200) : b.guard,
    } });
  }
});
return out;

// Log each escalated invoice once, so the same alert is not posted again tomorrow.
const out = [];
$input.all().forEach((item, i) => {
  const e = $('Split by kind').itemMatching(i).json;
  const failed = Boolean(item.json.error);
  for (const row of e.logRows) {
    out.push({ json: { logged_at: $now.toISO(), mode: 'slack', ...row,
      action: failed ? 'failed' : 'escalated', gmail_id: '',
      note: failed ? String(item.json.error?.message || item.json.error).slice(0, 200) : 'posted to Slack' } });
  }
});
return out;
